    .reg .b32 %r<64>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<16>;
    .shared .align 4 .b8 smem[10584];
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    ld.param.u32 %r3, [total];
    setp.ge.u32 %p1, %r2, %r3;
    @%p1 ret;
    // CTA decomposition: cta -> (n, oc_group, d, h_tile)
    rem.u32 %r4, %r2, 11;        // h tile index
    div.u32 %r5, %r2, 11;
    rem.u32 %r6, %r5, 254;       // d
    div.u32 %r7, %r5, 254;
    rem.u32 %r8, %r7, 8;         // oc group (8 channels per CTA)
    div.u32 %r9, %r7, 8;         // n
    mul.lo.u32 %r10, %r4, 25;    // h0
    mul.lo.u32 %r50, %r8, 8;     // oc0 = first output channel
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [out_ptr];
    mov.u32 %r11, smem;
    // Stage 8*27 = 216 weights (27 per channel) at smem+9720
    setp.lt.u32 %p2, %r1, 216;
    @!%p2 bra W_DONE;
    mad.lo.u32 %r12, %r50, 27, %r1;
    mul.wide.u32 %rd4, %r12, 4;
    add.u64 %rd5, %rd2, %rd4;
    ld.global.nc.f32 %f14, [%rd5];
    mul.lo.u32 %r13, %r1, 4;
    add.u32 %r14, %r11, %r13;
    st.shared.f32 [%r14+9720], %f14;
