    @%p3 bra L_DONE;
    rem.u32 %r16, %r15, 10;      // w
    div.u32 %r17, %r15, 10;
    rem.u32 %r18, %r17, 27;      // hh
    div.u32 %r19, %r17, 27;
    rem.u32 %r20, %r19, 3;       // kd
    div.u32 %r21, %r19, 3;       // c
    add.u32 %r22, %r10, %r18;    // gh = h0 + hh
    setp.lt.u32 %p4, %r22, 256;
    mad.lo.u32 %r23, %r9, 3, %r21;
    mad.lo.u32 %r24, %r23, 256, %r6;
    add.u32 %r24, %r24, %r20;
    mul.lo.u32 %r25, %r24, 2560;
    mad.lo.u32 %r26, %r22, 10, %r16;
    add.u32 %r27, %r25, %r26;
    mul.wide.u32 %rd6, %r27, 4;
    add.u64 %rd7, %rd1, %rd6;
    mov.f32 %f15, 0f00000000;
    @%p4 ld.global.nc.f32 %f15, [%rd7];
    mul.lo.u32 %r28, %r15, 4;
    add.u32 %r29, %r11, %r28;
    st.shared.f32 [%r29], %f15;
    add.u32 %r15, %r15, 256;
