    add.u32 %r39, %r37, %r38;
    mad.lo.u32 %r40, %r39, 10, %r30;
    mul.lo.u32 %r41, %r40, 4;
    add.u32 %r42, %r11, %r41;
    ld.shared.f32 %f8, [%r42];
