    mad.lo.u32 %r43, %r36, 3, %r35;
    mul.lo.u32 %r44, %r43, 4;
    add.u32 %r45, %r11, %r44;
    ld.shared.f32 %f9, [%r45+9720];
    fma.rn.f32 %f0, %f8, %f9, %f0;
    ld.shared.f32 %f9, [%r45+9828];
    fma.rn.f32 %f1, %f8, %f9, %f1;
    ld.shared.f32 %f9, [%r45+9936];
    fma.rn.f32 %f2, %f8, %f9, %f2;
    ld.shared.f32 %f9, [%r45+10044];
    fma.rn.f32 %f3, %f8, %f9, %f3;
    ld.shared.f32 %f9, [%r45+10152];
    fma.rn.f32 %f4, %f8, %f9, %f4;
    ld.shared.f32 %f9, [%r45+10260];
    fma.rn.f32 %f5, %f8, %f9, %f5;
    ld.shared.f32 %f9, [%r45+10368];
    fma.rn.f32 %f6, %f8, %f9, %f6;
    ld.shared.f32 %f9, [%r45+10476];
    fma.rn.f32 %f7, %f8, %f9, %f7;
    add.u32 %r35, %r35, 1;
    bra KH_LOOP;
KH_DONE:
    add.u32 %r34, %r34, 1;
    bra KD_LOOP;
KD_DONE:
    add.u32 %r33, %r33, 1;
    bra C_LOOP;
