    mad.lo.u32 %r46, %r9, 64, %r50;
    mad.lo.u32 %r47, %r46, 254, %r6;
    mad.lo.u32 %r48, %r47, 254, %r32;
    mad.lo.u32 %r49, %r48, 10, %r30;
    mul.wide.u32 %rd8, %r49, 4;
    add.u64 %rd9, %rd3, %rd8;
    st.global.f32 [%rd9], %f0;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f1;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f2;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f3;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f4;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f5;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f6;
    add.u64 %rd9, %rd9, 2580640;
    st.global.f32 [%rd9], %f7;
